use std::usize;

fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    assert!(n >= 2);

    // Because all pairwise sums are < 256, each value must be < 256 as well.
    // So we can use a small table indexed by value (0..=255).
    // To ensure lexicographically smallest (p, q), we scan q from left to right
    // and for each q, use the earliest p < q that can complete the target.
    let mut first_pos: [Option<usize>; 256] = [None; 256];

    for q in 0..n {
        let x = nums[q] as usize;
        // Under the assumption, x < 256.
        debug_assert!(x < 256);

        if target < nums[q] {
            // complement would underflow; no match possible for this q
        } else {
            let comp_u32 = target - nums[q];
            if comp_u32 < 256 {
                let c = comp_u32 as usize;
                if let Some(p) = first_pos[c] {
                    // p is the smallest index with value == c among indices < q
                    return (p, q);
                }
            }
        }

        // Record earliest occurrence of this value for future q's.
        if first_pos[x].is_none() {
            first_pos[x] = Some(q);
        }
    }

    // Problem statement guarantees a solution exists.
    unreachable!();
}